      text: "W\nU/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/auth.ts\n\nimport { createHmac, timingSafeEqual } from 'node:crypto';\nimport { config } from './config';\nimport { person } from './people';\nexport function sign(value: string, secret: string) {\n  return createHmac('sha256', secret).update(value).digest('hex');\n}\nexport function equal(a: string, b: string) {\n  const left = Buffer.from(a),\n    right = Buffer.from(b);\n  return left.length === right.length && timingSafeEqual(left, right);\n}\nexport function sessionToken(userId: string) {\n  return `${userId}.${sign(userId, config.sessionSecret)}`;\n}\nexport function actor(request: Request) {\n  const token = (request.headers.get('cookie') || '')\n    .split(';')\n    .map((s) => s.trim())\n    .find((s) => s.startsWith('banana_actor='))\n    ?.slice('banana_actor='.length);\n  if (!token) throw new HttpError(401, 'Select a person to continue.');\n  const [id, signature] = token.split('.');\n  const p = person(id);\n  if (!p || !signature || !equal(signature, sign(id, config.sessionSecret)))\n    throw new HttpError(401, 'Invalid session.');\n  return p;\n}\nexport function sameOrigin(request: Request) {\n  const origin = request.headers.get('origin');\n  if (origin) {\n    const parsed = new URL(origin);\n    if (\n      !['http:', 'https:'].includes(parsed.protocol) ||\n      parsed.host !== request.headers.get('host')\n    )\n      throw new HttpError(403, 'Origin not allowed.');\n  }\n}\nexport class HttpError extends Error {\n  constructor(\n    public status: number,\n    message: string,\n  ) {\n    super(message);\n  }\n}\n /(\n\n:U/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/auth.tsB\n\nVcall-bbb89888-de88-4747-b34a-cb87a59465c2-12\nfc_676a6234-9765-9c1d-9847-481b7986b1f5_3",
