      text: "\\\nZ/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/telemetry.ts\n\nimport { randomUUID } from 'node:crypto';\nimport { appDb } from './db';\nimport type { ToolContext } from './types';\nexport function recordEvent(ctx: ToolContext, kind: string, data: Record<string, unknown>) {\n  appDb()\n    .prepare('INSERT INTO events VALUES(?,?,?,?,?,?,?)')\n    .run(\n      randomUUID(),\n      ctx.runId,\n      ctx.userId,\n      ctx.conversationId,\n      kind,\n      JSON.stringify(data),\n      new Date().toISOString(),\n    );\n}\n \n\n:Z/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/telemetry.tsB\n\nVcall-6fcdea31-3879-416b-ba7e-67b8498bfc25-16\nfc_c93ecfff-9daf-9639-995d-b954d5476182_3",
