      text: "X\nV/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/types.ts\n\nexport type Person = {\n  id: string;\n  name: string;\n  role: 'customer' | 'operator';\n  initials: string;\n  color: string;\n};\nexport type Account = {\n  id: string;\n  userId: string;\n  label: string;\n  iban: string;\n  balanceCents: number;\n};\nexport type TransferInput = {\n  fromAccountId: string;\n  toAccountId: string;\n  amountCents: number;\n  concept: string;\n};\nexport type Operation = TransferInput & {\n  id: string;\n  userId: string;\n  reference: string;\n  createdAt: string;\n  status: 'completed';\n};\nexport type TransferProposal = {\n  fromAccountId: string;\n  fromLabel: string;\n  toAccountId: string;\n  toName: string | null;\n  toLabel: string | null;\n  amountCents: number;\n  concept: string;\n};\nexport type DispatchResult =\n  | { status: 'completed'; operation: Operation }\n  | { status: 'unknown'; reference: string; error: string };\nexport type ToolContext = {\n  userId: string;\n  conversationId: string | null;\n  runId: string;\n  intentId: string;\n  approvalId?: string;\n};\nexport type ActionResult = { status: string; [key: string]: unknown };\nexport type DocumentRecord = {\n  id: string;\n  title: string;\n  file: string;\n  version: number;\n  validFrom: string;\n  validTo: string | null;\n  audience: 'public' | 'internal';\n  family: string;\n};\nexport type Chunk = {\n  id: string;\n  documentId: string;\n  text: string;\n  title: string | null;\n  version: number | null;\n  validFrom: string | null;\n  validTo: string | null;\n  audience: string;\n  vector?: number[];\n};\nexport type SearchResult = Omit<Chunk, 'vector'> & { score: number };\nexport type IntentRecord = {\n  id: string;\n  status: string;\n  payload: TransferInput;\n  bankReference: string | null;\n  operationId: string | null;\n  error: string | null;\n  createdAt: string;\n  conversationId: string | null;\n  runId: string | null;\n};\nexport type Reconciliation = {\n  intentId: string;\n  reference: string | null;\n  amountCents: number;\n  appStatus: string;\n  bankStatus: 'completed' | 'not_found' | 'unverified';\n  operation: Operation | null;\n  finding: string | null;\n  fixable: boolean;\n};\nexport type CaseDetail = {\n  incident: {\n    id: string;\n    user_id: string;\n    conversation_id: string;\n    summary: string;\n    status: string;\n    created_at: string;\n  };\n  customer: Person | undefined;\n  lastMessage: { id: string; role: string; content: string; created_at: string } | undefined;\n  history: { id: string; role: string; content: string; created_at: string }[];\n  events: { id: string; kind: string; data: unknown; created_at: string }[];\n  intents: IntentRecord[];\n  bank: { accounts: Account[]; operations: Operation[] } | null;\n  bankError: string | null;\n  reconciliation: Reconciliation[];\n  gaps: string[];\n};\n n(\n\n:V/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/src/types.tsB\n\nVcall-5997fbcd-47b3-473e-9ce8-e53c2ba4b91a-21\nfc_feba5c4d-af3f-9396-9094-1c92ee6cb609_4",
